import time
import json
from datetime import datetime

data = []
next_id = 1

def handle(method, path, body):
    global data, next_id

    if path == '/messages':
        if method == 'GET':
            return (200, data)
        elif method == 'POST':
            try:
                payload = json.loads(body.decode('utf-8'))
                content = payload.get('content', '').strip()
                if not content:
                    return (400, {'error': '留言內容不能為空'})

                message = {
                    'id': next_id,
                    'content': content,
                    'timestamp': datetime.now().isoformat(),
                    'likes': 0
                }
                data.append(message)
                next_id += 1
                return (201, message)
            except Exception as e:
                return (400, {'error': '無效的請求數據'})
        else:
            return (405, {'error': '不支援的方法'})

    elif path == '/messages/sort/likes':
        if method == 'GET':
            # 按讚數排序（最多的在前）
            sorted_data = sorted(data, key=lambda x: x['likes'], reverse=True)
            return (200, sorted_data)
        else:
            return (405, {'error': '不支援的方法'})

    elif path.startswith('/messages/') and path.endswith('/like'):
        # 處理按讚
        parts = path.split('/')
        if len(parts) == 4:  # /messages/{id}/like
            try:
                message_id = int(parts[2])
                for msg in data:
                    if msg['id'] == message_id:
                        msg['likes'] += 1
                        return (200, msg)
                return (404, {'error': '留言不存在'})
            except ValueError:
                return (400, {'error': '無效的留言ID'})
        else:
            return (404, {'error': '找不到資源'})

    elif path.startswith('/messages/') and len(path.split('/')) == 3:
        # 處理刪除
        try:
            message_id = int(path.split('/')[-1])
            for i, msg in enumerate(data):
                if msg['id'] == message_id:
                    del data[i]
                    return (200, {'message': '留言已刪除'})
            return (404, {'error': '留言不存在'})
        except ValueError:
            return (400, {'error': '無效的留言ID'})

    else:
        return (404, {'error': '找不到資源'})

