document.addEventListener('DOMContentLoaded', () => {
    const messageForm = document.getElementById('messageForm');
    const authorInput = document.getElementById('authorInput');
    const messageInput = document.getElementById('messageInput');
    const messagesContainer = document.getElementById('messagesContainer');
    const sortByTimeBtn = document.getElementById('sortByTime');
    const sortByLikesBtn = document.getElementById('sortByLikes');
    const errorBox = document.getElementById('errorBox');

    let currentSort = 'time'; // 'time' 或 'likes'

    function showError(message) {
        errorBox.textContent = message;
        errorBox.hidden = false;
    }

    function clearError() {
        errorBox.textContent = '';
        errorBox.hidden = true;
    }

    // 等待 fetch 的結果並解析 JSON；失敗時丟出含有錯誤訊息的 Error
    async function readResponse(requestPromise) {
        let response;
        try {
            response = await requestPromise;
        } catch (err) {
            throw new Error('無法連線到伺服器，請稍後再試。');
        }
        let data = null;
        try {
            data = await response.json();
        } catch (err) {
            data = null;
        }
        if (!response.ok) {
            const detail = data && data.error ? data.error : '請求失敗（狀態碼 ' + response.status + '）';
            throw new Error(detail);
        }
        return data;
    }

    // 載入留言列表
    async function loadMessages() {
        try {
            let data;
            if (currentSort === 'likes') {
                data = await readResponse(fetch('api/messages/sort/likes', { method: 'GET' }));
            } else {
                data = await readResponse(fetch('api/messages', { method: 'GET' }));
            }
            const items = data && Array.isArray(data.items) ? data.items : [];
            displayMessages(items);
        } catch (error) {
            showError('載入留言失敗：' + error.message);
        }
    }

    function formatTime(value) {
        const d = new Date(value);
        if (isNaN(d.getTime())) return String(value || '');
        return d.toLocaleString('zh-TW');
    }

    // 顯示留言
    function displayMessages(messages) {
        messagesContainer.textContent = '';

        if (messages.length === 0) {
            const empty = document.createElement('p');
            empty.textContent = '目前沒有留言。';
            messagesContainer.appendChild(empty);
            return;
        }

        messages.forEach(msg => {
            const messageElement = document.createElement('div');
            messageElement.className = 'message';

            const text = document.createElement('p');
            text.textContent = msg.text;
            messageElement.appendChild(text);

            const info = document.createElement('div');
            info.className = 'message-info';

            const author = document.createElement('span');
            author.textContent = '作者: ' + msg.author;
            info.appendChild(author);

            const time = document.createElement('span');
            time.textContent = '時間: ' + formatTime(msg.created_at);
            info.appendChild(time);

            const likes = document.createElement('span');
            likes.textContent = '按讚: ' + msg.likes;
            info.appendChild(likes);

            const likeBtn = document.createElement('button');
            likeBtn.type = 'button';
            likeBtn.className = 'like-btn';
            likeBtn.dataset.id = msg.id;
            likeBtn.textContent = '按讚';
            info.appendChild(likeBtn);

            const deleteBtn = document.createElement('button');
            deleteBtn.type = 'button';
            deleteBtn.className = 'delete-btn';
            deleteBtn.dataset.id = msg.id;
            deleteBtn.textContent = '刪除';
            info.appendChild(deleteBtn);

            messageElement.appendChild(info);
            messagesContainer.appendChild(messageElement);
        });
    }

    // 按讚與刪除按鈕（事件委派）
    messagesContainer.addEventListener('click', async (e) => {
        const btn = e.target.closest('button');
        if (!btn || !btn.dataset.id) return;
        const id = btn.dataset.id;
        if (btn.classList.contains('like-btn')) {
            await likeMessage(id);
        } else if (btn.classList.contains('delete-btn')) {
            await deleteMessage(id);
        }
    });

    // 發表留言
    messageForm.addEventListener('submit', async (e) => {
        e.preventDefault();

        const author = authorInput.value.trim();
        const text = messageInput.value.trim();
        if (!author || !text) {
            showError('請輸入名字與留言內容。');
            return;
        }

        try {
            await readResponse(fetch('api/messages', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ author: author, text: text })
            }));
            clearError();
            messageInput.value = '';
            await loadMessages();
        } catch (error) {
            showError('發表留言失敗：' + error.message);
        }
    });

    // 按讚
    async function likeMessage(id) {
        try {
            await readResponse(fetch('api/messages/' + encodeURIComponent(id) + '/like', { method: 'PUT' }));
            clearError();
            await loadMessages();
        } catch (error) {
            showError('按讚失敗：' + error.message);
        }
    }

    // 刪除留言
    async function deleteMessage(id) {
        if (!confirm('確定要刪除這則留言嗎？')) return;
        try {
            await readResponse(fetch('api/messages/' + encodeURIComponent(id), { method: 'DELETE' }));
            clearError();
            await loadMessages();
        } catch (error) {
            showError('刪除留言失敗：' + error.message);
        }
    }

    // 切換排序方式
    sortByTimeBtn.addEventListener('click', () => {
        currentSort = 'time';
        clearError();
        loadMessages();
    });

    sortByLikesBtn.addEventListener('click', () => {
        currentSort = 'likes';
        clearError();
        loadMessages();
    });

    // 初始化載入留言
    loadMessages();
});

